#include <iostream>
#include <unordered_map>
#include <utility>

using namespace std;

long long go(int n, int h, unordered_map<pair<int,int>, long long, hash<pair<int,int>>> &v) {
    pair<int,int> key = make_pair(n, h);
    if (v.find(key) == v.end()) {
        long long result;
        if (n == 0) {
            result = 1;
        } else {
            long long sum = 0;
            for (int i = 0; i < n; ++i) {
                sum += go(i, h - 1, v) * go(n - 1 - i, h - 1, v);
            }
            result = (h != 0) ? sum : 0;
        }
        v[key] = result;
    }
    return v[key];
}

int main() {
    int n, h;
    cin >> n >> h;
    unordered_map<pair<int,int>, long long, hash<pair<int,int>>> v;
    cout << go(n, n, v) - go(n, max(0, h - 1), v) << endl;
    return 0;
}

struct hash_pair {
    size_t operator()(const pair<int,int>& p) const {
        auto hash1 = hash<int>{}(p.first);
        auto hash2 = hash<int>{}(p.second);
        return hash1 ^ (hash2 << 1);
    }
};

